interface QuickAnswerProps {
  calculatorId: string;
}

export function QuickAnswer({ calculatorId }: QuickAnswerProps) {
  const { i18n } = useTranslation();
  const lang = i18n.language === 'kk' ? 'kk' : 'ru';
  const data = QUICK_ANSWERS[calculatorId];
  if (!data) return null;
  const text = data[lang];
  const label = lang === 'kk' ? 'Қысқаша жауап' : 'Быстрый ответ';

  return (
    <div className="mb-6 p-5 bg-gradient-to-r from-blue-50 to-cyan-50 border border-blue-200 rounded-xl">
      <div className="flex items-start gap-3">
        <div className="flex-shrink-0 w-8 h-8 bg-blue-100 rounded-lg flex items-center justify-center">
          <Sparkles className="w-4 h-4 text-blue-600" />
        </div>
        <div className="flex-1">
          <div className="text-xs font-semibold text-blue-900 uppercase tracking-wide mb-1">
            {label}
          </div>
          <p className="text-sm text-blue-950 leading-relaxed">{text}</p>
        </div>
      </div>
    </div>
  );
}
